source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    colors = [value for value in counts if value != background]
    marker = max(colors, key=lambda value: counts[value])
    out = [row[:] for row in grid]
    for top in range(h - 2):
        for bottom in range(top + 2, h):
            for left in range(w - 2):
                for right in range(left + 2, w):
                    if (all(grid[top][c] == marker for c in range(left, right + 1)) and
                        all(grid[bottom][c] == marker for c in range(left, right + 1)) and
                        all(grid[r][left] == marker for r in range(top, bottom + 1)) and
                        all(grid[r][right] == marker for r in range(top, bottom + 1))):
                        for r in range(top + 1, bottom):
                            for c in range(left + 1, right):
                                if grid[r][c] == background:
                                    out[r][c] = 4
    return out
'''
